    };
    tick();
  } else {
    const at = q.get('t');
    const k = !at || at === 'end' ? track.length - 1 : track.findIndex((s) => s.t >= +at);
    apply(k < 0 ? track.length - 1 : k);
    renderer.render(scene, camera);
  }
